const qs=s=>document.querySelector(s);const qsa=s=>document.querySelectorAll(s);
const csrfToken=()=>{const meta=qs('meta[name="csrf-token"]');return meta?meta.getAttribute('content'):'';};
const drawCharts=()=>{qsa('[data-chart]').forEach(canvas=>{const ctx=canvas.getContext('2d');const seriesData=canvas.dataset.series?JSON.parse(canvas.dataset.series):null;if(seriesData){const sales=seriesData.map(point=>point.sales);const refunds=seriesData.map(point=>point.refunds);const max=Math.max(...sales,...refunds,1);ctx.clearRect(0,0,canvas.width,canvas.height);const drawLine=(values,color)=>{ctx.beginPath();ctx.strokeStyle=color;ctx.lineWidth=2;values.forEach((value,index)=>{const x=(canvas.width/(values.length-1||1))*index;const y=canvas.height-(value/max)*canvas.height;index===0?ctx.moveTo(x,y):ctx.lineTo(x,y);});ctx.stroke();};drawLine(sales,'#2563eb');drawLine(refunds,'#ef4444');}else{const points=JSON.parse(canvas.dataset.points||'[0]');const max=Math.max(...points,1);ctx.clearRect(0,0,canvas.width,canvas.height);ctx.beginPath();ctx.strokeStyle='#2563eb';ctx.lineWidth=2;points.forEach((value,index)=>{const x=(canvas.width/(points.length-1||1))*index;const y=canvas.height-(value/max)*canvas.height;index===0?ctx.moveTo(x,y):ctx.lineTo(x,y);});ctx.stroke();}});};
const bindCopy=()=>{document.addEventListener('click',event=>{const target=event.target.closest('[data-copy]');if(!target){return;}const value=target.getAttribute('data-copy');if(!value){return;}navigator.clipboard.writeText(value).then(()=>{target.classList.add('copied');setTimeout(()=>target.classList.remove('copied'),1500);}).catch(()=>{console.warn('Kopyalama başarısız');});});};
const bindMacros=()=>{qsa('[data-macro-select]').forEach(select=>{select.addEventListener('change',()=>{const option=select.options[select.selectedIndex];const body=option?option.getAttribute('data-body'):null;if(!body){return;}const textarea=select.form?select.form.querySelector('textarea[name="message"]'):null;if(textarea&&textarea.value.trim()===''){textarea.value=body;} });});};
document.addEventListener('DOMContentLoaded',()=>{drawCharts();bindCopy();bindMacros();});
